<section class="page-head"><span class="eyebrow">PATIENT ONBOARDING</span><h1>Create Patient Account</h1><p>Your profile powers appointments, family care, medical records and emergency services.</p></section><form class="form-card wide" method="post" enctype="multipart/form-data"><label>Profile Photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><span class="hint">Upload a clear profile photo (JPG, PNG or WEBP).</span></label><div class="grid2"><label>Full Name<input name="name" required></label><label>Phone Number<input name="phone" maxlength="15" required></label><label>Email<input type="email" name="email" required></label><label>Aadhaar Number<input name="aadhaar_no" maxlength="12" pattern="[0-9]{12}" required></label><label>PAN Number<input name="pan_no" maxlength="10" style="text-transform:uppercase" required></label><label>Date of Birth<input type="date" name="dob"></label><label>Gender<select name="gender"><option value="">Select</option><option>Male</option><option>Female</option><option>Other</option></select></label><label>Blood Group<select name="blood_group"><option value="">Select</option><option>A+</option><option>A-</option><option>B+</option><option>B-</option><option>AB+</option><option>AB-</option><option>O+</option><option>O-</option></select></label></div><?php include __DIR__.'/../address_fields.php';?><div class="grid2"><label>Emergency Contact Name<input name="emergency_contact_name"></label><label>Emergency Contact Phone<input name="emergency_contact_phone"></label><label>Password<input type="password" name="password" data-password required></label><label>Confirm Password<input type="password" name="confirm_password" required></label></div><div class="password-box"><b>Password instructions</b><span data-rule="len">○ At least 8 characters</span><span data-rule="upper">○ One uppercase letter</span><span data-rule="lower">○ One lowercase letter</span><span data-rule="num">○ One number</span><span data-rule="special">○ One special character</span><strong data-strength>Strength: —</strong></div><?php if(!empty($error)):?><div class="alert"><?=$error?></div><?php endif?><button class="btn primary">Create Patient Account</button></form>